import React from 'react';

const Footer = () => {
  return (
    <footer className="bg-gray-800 text-white text-center p-8">
      <div className="container mx-auto">
        <div className="space-x-6 mb-4">
          <a href="#home" className="hover:text-brand-green transition-colors">Home</a>
          <a href="#about" className="hover:text-brand-green transition-colors">About Us</a>
          <a href="#services" className="hover:text-brand-green transition-colors">Services</a>
          <a href="#contact" className="hover:text-brand-green transition-colors">Contact Us</a>
          <a href="#terms" className="hover:text-brand-green transition-colors">Terms and Conditions</a>
        </div>
        <p className="text-gray-400">&copy; {new Date().getFullYear()} Dietitian Pradeepa's Clinic. All Rights Reserved.</p>
      </div>
    </footer>
  );
};

export default Footer;
